import hashlib, json
from pathlib import Path
base=Path('/protected/previous_release')
if base.is_dir():
    man_path=base/'manifest.json'
else:
    man_path=base
raw=man_path.read_bytes()
man=json.loads(raw)
old=man.get('files_sha256') or {}
src=Path('/workspace/source')
cur={}
for p in src.rglob('*'):
    if p.is_file() and p.suffix in ('.py','.c'):
        rel=str(p.relative_to(src)).replace('\\','/')
        cur[rel]=hashlib.sha256(p.read_bytes()).hexdigest()
changed=[]; added=[]; unchanged=[]
for rel, digest in sorted(cur.items()):
    prev=old.get(rel)
    if prev is None:
        added.append({'path':rel,'sha256':digest})
    elif prev==digest:
        unchanged.append({'path':rel,'sha256':digest})
    else:
        changed.append({'path':rel,'sha256':digest,'baseline_sha256':prev})
removed=sorted(k for k in old if k.endswith(('.py','.c')) and k not in cur)
out={'baseline_manifest':str(man_path),'baseline_manifest_sha256':hashlib.sha256(raw).hexdigest(),'compared_suffixes':['.py','.c'],'changed':changed,'added':added,'unchanged':unchanged,'removed_from_source':removed}
Path('/output/change-index.json').write_text(json.dumps(out,indent=2)+'\n')
note='# Change index\n\nCompared current /workspace/source .py and .c files with files_sha256 in the approved previous_release manifest. Baseline manifest SHA-256 is '+out['baseline_manifest_sha256']+'. Changed: '+str(len(changed))+'. Added: '+str(len(added))+'. Unchanged: '+str(len(unchanged))+'. Baseline .py/.c names absent from the tree: '+str(len(removed))+'.\n\nChanged paths: '+', '.join(x['path'] for x in changed)+'.\nAdded paths: '+', '.join(x['path'] for x in added)+'.\nRemoved baseline paths: '+', '.join(removed)+'.\n\nLimits: only .py and .c were compared. Other manifest entries, the zip, and native/notify-launch were not checked. Hashes are of the current source bytes and the manifest map, not a rebuilt package.\n'
Path('/output/index-note.md').write_text(note)
print(len(note), len(changed), len(added), len(unchanged), len(removed))
print(out['baseline_manifest_sha256'])
